def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract opponent's moves compactly
    opp = [h[1] for h in history]

    # Track consecutive defections at the tail
    tail_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            tail_d += 1
        else:
            break

    # Track consecutive cooperations at the tail
    tail_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            tail_c += 1
        else:
            break

    # Overall and recent cooperation rates
    total_c = sum(1 for a in opp if a == 'C')
    total_rate = total_c / n

    window = opp[-12:] if n >= 12 else opp
    recent_c = sum(1 for a in window if a == 'C')
    recent_rate = recent_c / len(window)

    # Mutual defection run: how long have both been defecting?
    both_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            both_d += 1
        else:
            break

    # Very cooperative opponent: keep cooperating, rare probe
    if total_rate >= 0.92:
        if n < 90 and n % 23 == 0 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Very hostile opponent: defect, but occasionally probe to escape traps
    if total_rate <= 0.12:
        if both_d >= 4 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Strong sustained recent defection: retaliate firmly
    if tail_d >= 4:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent defected last
    if opp[-1] == 'D':
        # If we were cooperating and they just defected, retaliate but allow quick reset
        if history[-1][0] == 'C':
            if tail_d >= 2:
                return 'D'
            # Single defection: retaliate once with high probability
            if rng.random() < 0.85:
                return 'D'
            return 'C'
        else:
            # We defected too (DD). Try to break the deadlock.
            if both_d >= 3:
                if rng.random() < 0.55:
                    return 'C'
                return 'D'
            if recent_rate >= 0.5:
                return 'C'
            return 'D' if rng.random() < 0.6 else 'C'

    # Opponent cooperated last
    # If we defected last round, reciprocate with cooperation to rebuild
    if history[-1][0] == 'D':
        return 'C'

    # Both cooperated last: cooperate, with occasional probing if very late
    if n >= 92:
        # End-game: exploit cooperative opponents slightly, but avoid triggering
        # a retaliatory collapse. Only defect when opponent has been very nice.
        if total_rate >= 0.75 and recent_rate >= 0.7:
            if rng.random() < 0.6:
                return 'D'
        return 'C'

    # Mid-game fine-tuning based on recent cooperation
    if recent_rate >= 0.7:
        # Occasionally probe to test for exploitability, then revert
        if n % 19 == 0 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if recent_rate <= 0.35:
        # Opponent is drifting to defection; play cautious tit-for-tat
        if tail_c >= 1 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Moderate mixed opponent: cooperate but retaliate against repeated defection
    if tail_d >= 2:
        return 'D'
    return 'C'
